import os
import torch


class Config:
    # ==== System & Reproducibility ====
    SEED = 42
    DEVICE = "cuda" if torch.cuda.is_available() else "cpu"
    NUM_WORKERS = 4

    # ==== File Paths ====
    # Metadata paths (generated by previous steps)
    TRAIN_CSV = "./metadata/train.csv"
    VAL_CSV = "./metadata/val.csv"
    TEST_CSV = "./metadata/test.csv"
    SAMPLE_SUBMISSION = "./input/sample_submission.csv"

    # Working directory for caching and model checkpoints
    WORKING_DIR = "./working/idea_12"
    os.makedirs(WORKING_DIR, exist_ok=True)

    # Cache filenames (Explicit versioning to ensure cache invalidation)
    TRAIN_CACHE = os.path.join(WORKING_DIR, "train_data_idea_12.npz")
    VAL_CACHE = os.path.join(WORKING_DIR, "val_data_idea_12.npz")
    TEST_CACHE = os.path.join(WORKING_DIR, "test_data_idea_12.npz")

    # Model Checkpoint
    MODEL_PATH = os.path.join(WORKING_DIR, "best_model.pth")
    SUBMISSION_PATH = "./submission/submission.csv"
    os.makedirs(os.path.dirname(SUBMISSION_PATH), exist_ok=True)

    # ==== Data Parameters ====
    # Sequence length is fixed for this dataset
    SEQ_LENGTH = 107
    # Number of positions scored in the competition
    SEQ_SCORED = 68

    # Input features:
    # Sequence (A, G, C, U) = 4
    # Structure (., (, )) = 3
    # Loop Type (S, M, I, B, H, E, X) = 7
    # Total Input Channels = 14
    INPUT_CHANNELS = 14

    # Target Columns
    TARGET_COLS = ["reactivity", "deg_Mg_pH10", "deg_pH10", "deg_Mg_50C", "deg_50C"]
    # Columns specifically used for scoring (Masked Optimization)
    SCORED_COLS = ["reactivity", "deg_Mg_pH10", "deg_Mg_50C"]
    NUM_TARGETS = 5

    # ==== Model Architecture ====
    # Stage 1: Local Motif Extraction & Global Context
    # Exponential dilation to capture wide context
    STAGE1_DILATION_SCHEDULE = [1, 2, 4, 8, 16, 32]

    # Channel width / Growth rate
    # Set to 64 to ensure sufficient capacity for chemical motifs (Cite Lesson 00037)
    GROWTH_RATE = 64

    # Kernel size for convolutions
    KERNEL_SIZE = 3

    # Dropout rate for regularization within blocks
    DROPOUT = 0.1

    # Inter-stage compression dimension
    # Used to compress features before gathering partner features
    INTER_STAGE_DIM = 64

    # Global Aggregation (BiGRU)
    # Hidden size relative to growth rate or fixed
    GRU_HIDDEN_SIZE = 64  # Will be bidirectional, so output is 128

    # ==== Training Hyperparameters ====
    BATCH_SIZE = 64  # Increased for A100 utilization
    EPOCHS = 50
    LEARNING_RATE = 1e-3

    # Scheduler
    PATIENCE = 5
    FACTOR = 0.5
    MIN_LR = 1e-6

    # Early Stopping
    ES_PATIENCE = 10

    # Debugging
    DEBUG = False  # Set to True to run on a small subset
    DEBUG_SUBSET_SIZE = 100
